using System.Text.Json.Nodes;
using Orbit.Core;
static class LoaderChecks {
 public static int Run(string root,string minecraft){try{RunAsync(root,minecraft).GetAwaiter().GetResult();return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
 static async Task RunAsync(string root,string minecraft){using var http=new HttpClient();http.DefaultRequestHeaders.UserAgent.ParseAdd("ORBIT/0.7.0");int checks=0;foreach(var (name,endpoint) in new[]{("fabric-loader","https://meta.fabricmc.net/v2/versions/loader/1.21.1"),("quilt-loader","https://meta.quiltmc.org/v3/versions/loader/1.21.1")}){string folder=Path.Combine(root,name+"-"+Guid.NewGuid().ToString("N"));string versionFolder=Path.Combine(folder,"versions","1.21.1");Directory.CreateDirectory(versionFolder);foreach(var ext in new[]{".json",".jar"})File.Copy(Path.Combine(minecraft,"versions","1.21.1","1.21.1"+ext),Path.Combine(versionFolder,"1.21.1"+ext));var metadata=JsonNode.Parse(await http.GetStringAsync(endpoint))!.AsArray();string version=metadata.First()!["loader"]!["version"]!.ToString();using var packs=new Modpacks();string id=await packs.InstallLoaderAsync(folder,new PackIndex("Probe","1.21.1",name,version,Array.Empty<PackFile>()),null,CancellationToken.None);var profile=Versions.Resolve(folder,id);if(profile.MainClass==Versions.Resolve(folder,"1.21.1").MainClass||!profile.Libraries.Keys.Any(k=>k.Contains(name=="fabric-loader"?"fabric-loader":"quilt-loader")))throw new Exception("Loader profile not provisioned");checks++;Console.WriteLine("PASS "+name+" "+version+" verified libraries and launch profile");}Console.WriteLine("PASS "+checks+" live loader checks. No game launched.");}
}
